"""Polynomial approximations used by the package, fitted from mpmath.

    uv run --with mpmath==1.4.1 python testdata/gen/fit.py NAME > zz_NAME_coeffs.go

Method: on each piece [a, b] the function is interpolated at Chebyshev
nodes of the first kind (near-minimax: within a factor 1 + (2/pi) log n of
the best uniform approximation, Rivlin, "Chebyshev Polynomials", 1990,
Thm 1.2/sec. 3.5) at 200-bit precision, converted to the monomial basis in
s = t - c around the midpoint c (well conditioned because |s| <= (b-a)/2 is
small), and the degree is the smallest whose interpolation error, checked on
a dense grid against mpmath, is below 2^-64 relative. The rounding of the
coefficients to float64 then dominates, which is the point: the polynomial
is not the error source, the final rounding is. The constant term is also
emitted as a double-double (its low part c0lo) so that callers can evaluate
c0 + s*q(s) with the leading term exact (evalPiecesDD); so is the linear
coefficient (c1lo), for callers that evaluate c0 + s*c1 + s^2*q2(s) with the
first two terms exact (estPiece.evalLow).
"""

import sys

import mpmath
from mpmath import mp, mpf

mp.prec = 200


def cheb_interp(f, a, b, n):
    """Coefficients (monomial, ascending in s = t - c) of the degree-n
    Chebyshev interpolant of f on [a, b]."""
    a, b = mpf(a), mpf(b)
    c, h = (a + b) / 2, (b - a) / 2
    nodes = [mp.cos(mp.pi * (k + mpf(1) / 2) / (n + 1)) for k in range(n + 1)]
    vals = [f(c + h * x) for x in nodes]
    # Chebyshev coefficients
    cc = []
    for j in range(n + 1):
        s = mp.fsum(vals[k] * mp.cos(mp.pi * j * (k + mpf(1) / 2) / (n + 1)) for k in range(n + 1))
        cc.append(2 * s / (n + 1))
    cc[0] /= 2
    # T_j(x) to monomials in x, then x = s/h
    mono = [mpf(0)] * (n + 1)
    Tprev, Tcur = [mpf(1)], [mpf(0), mpf(1)]
    for j in range(n + 1):
        T = Tprev if j == 0 else Tcur if j == 1 else None
        if j >= 2:
            T = [mpf(0)] + [2 * v for v in Tcur]
            for i, v in enumerate(Tprev):
                T[i] -= v
            Tprev, Tcur = Tcur, T
        for i, v in enumerate(T):
            mono[i] += cc[j] * v
    return c, [mono[i] / h**i for i in range(n + 1)]


def fit(f, a, b, tol=mpf(2) ** -64, nmax=40):
    for n in range(4, nmax):
        c, co = cheb_interp(f, a, b, n)
        worst = mpf(0)
        for k in range(401):
            t = mpf(a) + (mpf(b) - mpf(a)) * k / 400
            if t == c:
                pass
            p = mp.fsum(co[i] * (t - c) ** i for i in range(len(co)))
            fv = f(t)
            worst = max(worst, abs((p - fv) / fv))
        if worst < tol:
            return c, co, n, worst
    raise SystemExit("no convergence on [%s, %s]" % (a, b))


def emit_pieces(name, doc, f, edges):
    print("// Code generated by testdata/gen/fit.py %s; DO NOT EDIT." % name)
    print("//")
    print("// %s" % doc)
    print("// Chebyshev interpolants converted to monomials in s = t - c;")
    print("// interpolation error < 2^-64 relative on each piece, checked")
    print("// against mpmath %s at 200 bits." % mpmath.__version__)
    print()
    print("package special")
    print()
    print("var %s = [...]polyPiece{" % name)
    for a, b in zip(edges, edges[1:]):
        c, co, n, worst = fit(f, a, b)
        print("\t// [%s, %s]: degree %d, max interpolation error %s" % (a, b, n, mpmath.nstr(worst, 3)))
        c0 = co[0]
        c0lo = float(c0 - mpf(float(c0)))
        c1lo = float(co[1] - mpf(float(co[1])))
        print("\t{lo: %r, hi: %r, c: %r, c0lo: %r, c1lo: %r, coef: []float64{" % (float(a), float(b), float(c), c0lo, c1lo))
        for v in reversed(co):  # descending, for Horner
            print("\t\t%s," % repr(float(v)))
        print("\t}},")
    print("}")


def gamma1p_F(t):
    # (Gamma(1+t) - 1) / (t (t - 1)); removable singularities at 0 and 1.
    if t == 0:
        return +mp.euler
    if t == 1:
        return 1 - mp.euler
    return (mp.gamma(1 + t) - 1) / (t * (t - 1))


def sinpi_G(u):
    # (sin(pi sqrt u)/sqrt u - pi) / u, u = r^2 in [0, 1/16]
    if u == 0:
        return -mp.pi**3 / 6
    r = mp.sqrt(u)
    return (mp.sin(mp.pi * r) / r - mp.pi) / u


def cospi_H(u):
    # (cos(pi sqrt u) - 1) / u
    if u == 0:
        return -mp.pi**2 / 2
    return (mp.cos(mp.pi * mp.sqrt(u)) - 1) / u


_psi_root = None


def psi_root():
    global _psi_root
    if _psi_root is None:
        with mp.workprec(400):
            _psi_root = mp.findroot(mp.digamma, mpf("1.4616321449683623412626595423257213284682"))
    return _psi_root


def digamma1p_D(t):
    # psi(1+t) / (t - r), r = x0 - 1 (x0 the positive zero of psi)
    r = psi_root() - 1
    if abs(t - r) < mpf(2) ** -150:
        with mp.workprec(400):
            return mp.polygamma(1, psi_root())
    with mp.workprec(400):
        return mp.digamma(1 + t) / (t - r)


def erf_E(u):
    # erf(sqrt u)/sqrt u
    if u == 0:
        return 2 / mp.sqrt(mp.pi)
    r = mp.sqrt(u)
    return mp.erf(r) / r


def erfcx_x(x):
    with mp.workprec(mp.prec + 60):
        return mp.exp(x * x) * mp.erfc(x)


def erfcx_G(u):
    # x erfcx(x) with u = 1/x^2
    if u == 0:
        return 1 / mp.sqrt(mp.pi)
    x = 1 / mp.sqrt(u)
    with mp.workprec(mp.prec + 200):
        return x * mp.exp(x * x) * mp.erfc(x)


def zeta_R(s):
    # zeta(s) - 1/(s-1), entire
    if s == 1:
        return +mp.euler
    with mp.workprec(mp.prec + 60):
        return mp.zeta(s) - 1 / (s - 1)


def zeta_g(s):
    # (zeta(s) - 1) 2^s on [2, 64]
    with mp.workprec(mp.prec + 80):
        return (mp.zeta(s) - 1) * mp.power(2, s)


def ellipk_m(m):
    return mp.ellipk(m)


def ellipe_m(m):
    return mp.ellipe(m)


def ellipk_A(p):
    # K(1-p) + log(p) K(p)/pi, analytic at p = 0 (value log 4)
    if p == 0:
        return mp.log(4)
    with mp.workprec(mp.prec + 60):
        return mp.ellipk(1 - p) + mp.log(p) * mp.ellipk(p) / mp.pi


def ellipe_A(p):
    # E(1-p) + log(p) (K(p) - E(p))/pi, analytic at p = 0 (value 1)
    if p == 0:
        return mpf(1)
    with mp.workprec(mp.prec + 60):
        return mp.ellipe(1 - p) + mp.log(p) * (mp.ellipk(p) - mp.ellipe(p)) / mp.pi


def ellip_D(p):
    # (K(p) - E(p))/p, analytic, pi/4 at 0
    if p == 0:
        return mp.pi / 4
    with mp.workprec(mp.prec + 60):
        return (mp.ellipk(p) - mp.ellipe(p)) / p


def erfinv_R(t):
    # erfinv(sqrt t)/sqrt t on [0, 1/4]; erfinv(p) = p R(p^2) for |p| <= 1/2
    if t == 0:
        return mp.sqrt(mp.pi) / 2
    r = mp.sqrt(t)
    with mp.workprec(mp.prec + 40):
        return mp.erfinv(r) / r


def erfcinv_X(w):
    # the x with erfc(x) = exp(-w^2): erfcinv(q) = X(sqrt(-log q))
    with mp.workprec(mp.prec + 40):
        x0 = w if w > 2 else mp.erfinv(1 - mp.exp(-w * w))
        return mp.findroot(lambda x: mp.log(mp.erfc(x)) + w * w, x0,
                           tol=mpf(2) ** -(mp.prec + 20))


def digamma_x(x):
    return mp.digamma(x)


JOBS = {
    "digammaMidPieces": ("digammaMidPieces: ψ(x) on [2, 10] (widths 1/4 on [2, 3], 1/2 on [3, 4], 1 on [4, 10]).",
                         digamma_x, [2.0, 2.25, 2.5, 2.75, 3.0, 3.5, 4.0, 5.0, 6.0, 7.0, 8.0, 9.0, 10.0]),
    "erfInvSmallPieces": ("erfInvSmallPieces: R(t) = erfinv(√t)/√t on [0, 1/4]; erfinv(p) = p R(p²) for |p| <= 1/2.",
                          erfinv_R, [0.0, 0.125, 0.25]),
    "erfcInvPieces": ("erfcInvPieces: X(w) = erfcinv(exp(-w²)) on [0.8125, 31.0625] (q = exp(-w²) < 1/2; widths 1/4, 1, 2, 4).",
                      erfcinv_X, [0.8125 + 0.25 * k for k in range(10)] + [4.0625, 5.0625, 6.0625, 7.0625, 9.0625,
                                                                             11.0625, 15.0625, 19.0625, 23.0625,
                                                                             27.0625, 31.0625]),
    "ellipDPieces": ("ellipDPieces: D(p) = (K(p) - E(p))/p on [0, 0.5] (no cancellation as p -> 0).",
                     ellip_D, [0.0, 0.125, 0.25, 0.375, 0.5]),
    "zetaTailPieces": ("zetaTailPieces: g(s) = (ζ(s) - 1) 2^s on [6, 64].",
                       zeta_g, [6.0 + 2 * k for k in range(30)]),
    "ellipKPieces": ("ellipKPieces: K(m) on [-1, 0.5].",
                     ellipk_m, [-1.0, -0.75, -0.5, -0.25, 0.0, 0.25, 0.5]),
    "ellipEPieces": ("ellipEPieces: E(m) on [-1, 0.5].",
                     ellipe_m, [-1.0, -0.75, -0.5, -0.25, 0.0, 0.25, 0.5]),
    "ellipKLogPieces": ("ellipKLogPieces: A(p) = K(1-p) + log(p) K(p)/π on [0, 0.5] (DLMF 19.12.1 structure).",
                        ellipk_A, [0.0, 0.125, 0.25, 0.375, 0.5]),
    "ellipELogPieces": ("ellipELogPieces: A(p) = E(1-p) + log(p) (K(p) - E(p))/π on [0, 0.5].",
                        ellipe_A, [0.0, 0.125, 0.25, 0.375, 0.5]),
    "zetaPieces": ("zetaPieces: R(s) = ζ(s) - 1/(s-1) on [-1, 6] (entire: ζ's only pole removed).",
                   zeta_R, [-1.0 + 0.5 * k for k in range(15)]),
    "erfSmallPieces": ("erfSmallPieces: E(u) = erf(√u)/√u on [0, 1/4]; erf(x) = x E(x²) for |x| <= 1/2.",
                       erf_E, [0.0, 0.25]),
    "erfcxPieces": ("erfcxPieces: erfcx(x) = exp(x²) erfc(x) on [0.5, 8].",
                    erfcx_x, [0.5 + 0.5 * k for k in range(16)]),
    "erfcxTailPieces": ("erfcxTailPieces: G(u) = x erfcx(x), u = 1/x², on [0, 1/64] (x >= 8).",
                        erfcx_G, [0.0, 1.0 / 128, 1.0 / 64]),
    "digamma1pPieces": ("digamma1pPieces: D(t) = ψ(1+t)/(t - r) on [0, 1], r = x0 - 1, ψ(x0) = 0.",
                        digamma1p_D, [0.0, 0.25, 0.5, 0.75, 1.0]),
    "sinPiPieces": ("sinPiPieces: G(u) = (sin(π√u)/√u - π)/u on [0, 1/16]; sin(πr) = r(π + r²G(r²)).",
                    sinpi_G, [0, 0.0625]),
    "cosPiPieces": ("cosPiPieces: H(u) = (cos(π√u) - 1)/u on [0, 1/16]; cos(πr) = 1 + r²H(r²).",
                    cospi_H, [0, 0.0625]),
    "gamma1pPieces": ("gamma1pPieces: F(t) = (Γ(1+t) - 1) / (t (t-1)) on [-0.5, 1].",
                      gamma1p_F, [-0.5, -0.25, 0.0, 0.25, 0.5, 0.75, 1.0]),
}

if __name__ == "__main__":
    name = sys.argv[1]
    doc, f, edges = JOBS[name]
    emit_pieces(name, doc, f, edges)
